$('#activity-field').onpointerenter=()=>{fieldFrozenAt=performance.now()};$('#activity-field').onpointermove=e=>{const hit=hitField(e),t=$('#tooltip');$('#activity-field').style.cursor=hit?'pointer':'default';if(!hit){t.hidden=true;return}t.textContent=`${hit.b.date} · ${name(hit.b.id)} · ${hit.b.n} transactions`;t.hidden=false;t.style.left=Math.min(innerWidth-220,e.clientX+14)+'px';t.style.top=e.clientY+15+'px'};$('#activity-field').onpointerleave=()=>{if(fieldFrozenAt)fieldEpoch+=performance.now()-fieldFrozenAt;fieldFrozenAt=0;$('#tooltip').hidden=true};$('#activity-field').onclick=e=>{const hit=hitField(e);if(hit){$('#activity-action').value=hit.b.id;choosePeriod(hit.b.date+'-01');$('#tooltip').hidden=true;$('.table-heading').scrollIntoView({behavior:'smooth',block:'start'})}};
